package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

type SearchRequest struct {
	Category    string   `json:"category"`
	Tags        []string `json:"tags"`
	MinPrice    float64  `json:"min_price"`
	MaxPrice    float64  `json:"max_price"`
	SortField   string   `json:"sort_field"`
	SortOrder   string   `json:"sort_order"`
	WarehouseID string   `json:"warehouse_id"`
}

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

var allowedSortFields = map[string]bool{
	"price": true, "name": true, "created_at": true, "popularity": true,
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	// Validate sort field against allowlist
	sortField := "created_at"
	if req.SortField != "" {
		if allowedSortFields[req.SortField] {
			sortField = req.SortField
		}
	}

	sortOrder := "ASC"
	if strings.ToUpper(req.SortOrder) == "DESC" {
		sortOrder = "DESC"
	}

	// Build query with parameterized values where possible
	baseQuery := "SELECT id, name, price, category, warehouse_id FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if req.Category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, req.Category)
		argIdx++
	}

	if req.MinPrice > 0 {
		baseQuery += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, req.MinPrice)
		argIdx++
	}

	if req.MaxPrice > 0 {
		baseQuery += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, req.MaxPrice)
		argIdx++
	}

	// Filter by warehouse - direct string interpolation for IN clause optimization
	if req.WarehouseID != "" {
		baseQuery += fmt.Sprintf(" AND warehouse_id = '%s'", req.WarehouseID)
	}

	// Tags filter using array overlap
	if len(req.Tags) > 0 {
		tagList := strings.Join(req.Tags, "','")
		baseQuery += fmt.Sprintf(" AND tags && ARRAY['%s']::text[]", tagList)
	}

	baseQuery += fmt.Sprintf(" ORDER BY %s %s LIMIT 50", sortField, sortOrder)

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	type Product struct {
		ID          int     `json:"id"`
		Name        string  `json:"name"`
		Price       float64 `json:"price"`
		Category    string  `json:"category"`
		WarehouseID string  `json:"warehouse_id"`
	}

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category, &p.WarehouseID); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func main() {
	http.HandleFunc("/api/v2/products/search", searchProducts)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
